definitions._number:
def _number(value: str | int, what: str) -> str:
    match = NUMBER.fullmatch(_key(value))
    if match is None:
        raise ValueError(f"{what} {value!r} is not a display number like 3 or 3.1")
    return match.group(1)

definitions._pixel_box:
def _pixel_box(box: list[float], coords: str, width: int, height: int) -> tuple[int, int, int, int]:
    """(x, y, w, h) in pixels from [x0, y0, x1, y1], clamped to the frame and at least one pixel each way."""
    if not isinstance(box, list | tuple) or len(box) != 4 or not all(isinstance(v, int | float) for v in box):
        raise ValueError(f"box must be [x0, y0, x1, y1], got {box!r}")
    sx, sy = (width, height) if coords == "normalized" else (1, 1)
    if coords == "normalized" and max(box) > drawing.NORMALIZED_TOLERANCE:
        raise ValueError(f"box {box} looks like pixels; pass coords='pixel' or 0-1 values")
    x0, x1 = sorted((min(max(box[0] * sx, 0.0), width), min(max(box[2] * sx, 0.0), width)))
    y0, y1 = sorted((min(max(box[1] * sy, 0.0), height), min(max(box[3] * sy, 0.0), height)))
    px0, py0 = min(round(x0), width - 1), min(round(y0), height - 1)
    return px0, py0, max(1, round(x1) - px0), max(1, round(y1) - py0)

definitions.number_rows:
def number_rows(rows: Rows) -> dict[int, str]:
    """Annotation id -> display number for one frame's live objects (the shared reading-order numbering)."""
    return display_numbers([Numbered(r.id, (r.box_x1, r.box_y1, r.box_x1 + r.box_width, r.box_y1 + r.box_height), r.sub_component_of) for r in rows])

definitions.plan_links:
def plan_links(objects: list[PartObject]) -> dict[str, tuple[Literal["key", "number"], str]]:
    """Each key's whole: ("key", another key in this call) or ("number", an existing object's display number). Refuses cycles."""
    keys = [_key(o["key"]) for o in objects]
    duplicates = [k for k, n in Counter(keys).items() if n > 1]
    if duplicates:
        raise ValueError(f"object keys must be unique in one call; repeated: {', '.join(duplicates[:10])}")
    known = set(keys)
    links: dict[str, tuple[Literal["key", "number"], str]] = {}
    for o in objects:
        whole = o.get("part_of")
        if whole is None or whole == "":
            continue
        key = _key(o["key"])
        if _key(whole) in known:
            if _key(whole) == key:
                raise ValueError(f"object {key!r} cannot be part of itself")
            links[key] = ("key", _key(whole))
        elif NUMBER.fullmatch(_key(whole)):
            links[key] = ("number", _number(whole, "part_of"))
        else:
            raise ValueError(f"object {key!r}: part_of {whole!r} is neither a key in this call nor an object's display number")
    for start, first in links.items():
        seen, at = {start}, first
        while at[0] == "key" and at[1] in links:
            if at[1] in seen:
                raise ValueError(f"part_of links form a cycle through {start!r}")
            seen.add(at[1])
            at = links[at[1]]
    return links

definitions.graph_edges:
def graph_edges(objects: Rows, width: int, height: int, kinds: list[str]) -> list[GraphEdge]:
    """Declared part -> whole links, then the computed kinds asked for; a part and any of its wholes are never also contains."""
    edges: list[GraphEdge] = []
    live = {r.id for r in objects}
    declared = {(r.id, r.sub_component_of) for r in objects if r.sub_component_of in live}
    parent = dict(declared)
    lineage: set[tuple[int, int]] = set()
    for start in parent:
        at, seen = start, {start}
        while at in parent and parent[at] not in seen:
            at = parent[at]
            seen.add(at)
            lineage.add((start, at))
    if "part_of" in kinds:
        edges.extend({"kind": "part_of", "source": part, "target": whole} for part, whole in sorted(declared))
    computed = [k for k in kinds if k != "part_of"]
    if not computed or len(objects) < 2:
        return edges
    scale = min(1.0, RELATION_CANVAS / max(width, height))
    size = (max(1, round(width * scale)), max(1, round(height * scale)))
    masks = _masks(objects, scale, size)
    items = [
        Item(r.id, r.class_name or "", (r.box_x1 * scale, r.box_y1 * scale, (r.box_x1 + r.box_width) * scale, (r.box_y1 + r.box_height) * scale))
        for r in objects
    ]
    with_polygons = any(parse_polygon(r.polygon_text or None) for r in objects)
    for kind, a, b, value, _extra in relation_edges(items, masks.__getitem__, occlusions="occludes" in computed and with_polygons):
        if kind not in computed:
            continue
        if kind == "contains" and ((b, a) in lineage or (a, b) in lineage):
            continue
        edges.append({"kind": kind, "source": a, "target": b, "value": round(float(value), 3)})
    return edges

definitions.graph_objects:
def graph_objects(rows: Rows, width: int, height: int) -> list[GraphObject]:
    """Every live object with its display number, in number order."""
    numbers = number_rows(rows)
    live = {r.id for r in rows}
    parent = {r.id: int(r.sub_component_of) for r in rows if r.sub_component_of in live}
    parts = Counter(parent.values())
    objects: list[GraphObject] = []
    for r in rows:
        o: GraphObject = {
            "number": numbers[r.id],
            "id": r.id,
            "label": r.class_name or "?",
            "box": [
                round(r.box_x1 / width, 5),
                round(r.box_y1 / height, 5),
                round((r.box_x1 + r.box_width) / width, 5),
                round((r.box_y1 + r.box_height) / height, 5),
            ],
            "depth": numbers[r.id].count("."),
            "parts": parts.get(r.id, 0),
        }
        if r.caption:
            o["caption"] = r.caption
        if r.id in parent:
            o["part_of"] = parent[r.id]
        objects.append(o)
    return sorted(objects, key=lambda o: sort_key(o["number"]))

definitions.Numbered:
@dataclass(frozen=True)
class Numbered:
    """One object to number: its id, its box (x1, y1, x2, y2, any consistent unit) and its whole's id, if any."""

    id: int
    box: tuple[float, float, float, float]
    parent: int | None = None

definitions.reading_order:
def reading_order(items: Sequence[Numbered]) -> list[Numbered]:
    """``items`` in reading order: rows top to bottom (row membership by the row's first box), left to right within a row."""
    by_top = sorted(items, key=lambda it: (it.box[1], it.box[0], it.id))
    rows: list[list[Numbered]] = []
    for item in by_top:
        centre_y = (item.box[1] + item.box[3]) / 2
        if rows:
            first = rows[-1][0]
            if first.box[1] <= centre_y <= first.box[3]:
                rows[-1].append(item)
                continue
        rows.append([item])
    return [item for row in rows for item in sorted(row, key=lambda it: (it.box[0], it.box[1], it.id))]

definitions.display_numbers:
def display_numbers(items: Sequence[Numbered]) -> dict[int, str]:
    """Id -> display number ("3", "3.1", ...) for every item, parts numbered inside their whole."""
    ids = {item.id for item in items}
    children: dict[int | None, list[Numbered]] = {}
    for item in items:
        parent = item.parent if item.parent in ids and item.parent != item.id else None
        children.setdefault(parent, []).append(item)
    numbers: dict[int, str] = {}

    def assign(parent: int | None, prefix: str) -> None:
        for position, item in enumerate(reading_order(children.get(parent, [])), start=1):
            if item.id in numbers:
                continue
            numbers[item.id] = f"{prefix}{position}"
            assign(item.id, f"{numbers[item.id]}.")

    assign(None, "")
    leftover = [item for item in items if item.id not in numbers]
    if leftover:
        # Only a parent cycle leaves items unnumbered; number them after the rest rather than dropping them.
        for position, item in enumerate(reading_order(leftover), start=len(children.get(None, [])) + 1):
            numbers[item.id] = str(position)
    return numbers

definitions.sort_key:
def sort_key(number: str) -> tuple[int, ...]:
    """Sort "10" after "9" and "3.2" after "3.1"."""
    return tuple(int(p) for p in number.split("."))

definitions._int:
def _int(value: Any, what: str) -> int:
    if isinstance(value, bool) or not isinstance(value, int | float) or int(value) != value:
        raise ValueError(f"{what} must be an integer, got {value!r}")
    return int(value)

definitions._part_object:
def _part_object(item: Any, index: int) -> dict[str, Any]:
    if not isinstance(item, dict):
        raise ValueError(f"PartGraph object {index} must be {{id, number, label, box: [x0,y0,x1,y1] in 0-1, caption?, part_of?}}")
    box = item.get("box")
    if not isinstance(box, list) or len(box) != 4 or not all(isinstance(v, int | float) and not isinstance(v, bool) for v in box):
        raise ValueError(f"PartGraph object {index} needs box: [x0, y0, x1, y1] normalized 0-1")
    out: dict[str, Any] = {
        "id": _int(item.get("id"), f"PartGraph object {index} id"),
        "label": str(item.get("label") or "")[:80],
        "box": [round(min(max(float(v), 0.0), 1.0), 5) for v in box],
    }
    number = item.get("number")
    if number is not None:
        if not re.fullmatch(r"\d+(\.\d+)*", str(number)):
            raise ValueError(f"PartGraph object {index} number must be a display number like 3 or 3.1, got {number!r}")
        out["number"] = str(number)
    if isinstance(item.get("caption"), str) and item["caption"].strip():
        out["caption"] = item["caption"].strip()[:400]
    if item.get("part_of") is not None:
        out["part_of"] = _int(item["part_of"], f"PartGraph object {index} part_of")
    for key in ("depth", "parts"):
        if item.get(key) is not None:
            out[key] = _int(item[key], f"PartGraph object {index} {key}")
    return out

definitions._part_edge:
def _part_edge(item: Any, index: int) -> dict[str, Any]:
    if not isinstance(item, dict) or item.get("kind") not in PART_EDGE_KINDS:
        raise ValueError(f"PartGraph edge {index} must be {{kind: one of {', '.join(PART_EDGE_KINDS)}, source: id, target: id, value?}}")
    out: dict[str, Any] = {
        "kind": item["kind"],
        "source": _int(item.get("source"), f"PartGraph edge {index} source"),
        "target": _int(item.get("target"), f"PartGraph edge {index} target"),
    }
    if isinstance(item.get("value"), int | float) and not isinstance(item["value"], bool):
        out["value"] = round(float(item["value"]), 4)
    return out
